"""Prebuilt General/texture archives use generated bytes and private game/profile folders."""
import gzip
import json
import os
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch

from ba2_fixture import general_archive, texture_archive

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts" / "game"))
sys.path.insert(0, str(ROOT / "src"))
import exp_install as exp  # noqa: E402
from fo4sf.workshop import piece_icons  # noqa: E402


class PrepackedTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.stage = self.root / "stage"
        self.data = self.root / "game" / "Data"
        self.plugins = self.root / "local" / "Starfield" / "Plugins.txt"
        self.data.mkdir(parents=True)
        self.plugins.parent.mkdir(parents=True)
        self.original = b"\xef\xbb\xbf# owner\r\n*FO4Port.esm\r\n"
        self.plugins.write_bytes(self.original)
        self.resources = {"Terrain/World.btd": b"synthetic terrain"}
        self.textures = {"Textures/FO4SF/icon.dds": piece_icons.dds(1, "synthetic")}
        for name, content in {**self.resources, **self.textures}.items():
            path = self.stage / "Data" / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)
        (self.stage / "Experiment.esm").write_bytes(b"synthetic plugin")
        # The selected Main archive may live outside the stage and use another basename.
        self.main = self.root / "prebuilt" / "selected.ba2"
        self.main.parent.mkdir()
        self.main.write_bytes(general_archive(self.resources))
        self.texture = self.main.with_name("Experiment - Textures.ba2")
        self.texture.write_bytes(texture_archive(self.textures))
        self.argv = ["install", "--exp-dir", str(self.stage), "--starfield", str(self.data.parent),
                     "--pack", "--prepacked", str(self.main), "--textures-archive"]
        environment = patch.dict(os.environ, {"LOCALAPPDATA": str(self.plugins.parent.parent)})
        environment.start()
        self.addCleanup(environment.stop)

    def snapshot(self, root):
        return {p.relative_to(root).as_posix(): p.read_bytes() for p in root.rglob("*") if p.is_file()}

    def install_without_building(self):
        with patch.object(exp, "build_ba2", side_effect=AssertionError("prepacked must never build")) as build, \
                patch.object(exp.subprocess, "run", side_effect=AssertionError("no external tools")) as process:
            try:
                exp.main(self.argv)
            finally:
                build.assert_not_called()
                process.assert_not_called()

    def assert_refused(self, reason="archive"):
        before = self.snapshot(self.root)
        with self.assertRaisesRegex(SystemExit, reason):
            self.install_without_building()
        self.assertEqual(self.snapshot(self.root), before)
        self.assertFalse((self.data / exp.RECORD).exists())

    def test_combined_prebuilt_archives_install_relaunch_remove_without_build(self):
        owner = self.data / "FO4Port.deploy.json"
        owner.write_bytes(b'{"files": [], "complete": true}')
        before = self.snapshot(self.root)
        self.install_without_building()
        record = (self.data / exp.RECORD).read_bytes()
        receipt = json.loads(record)
        self.assertTrue(receipt["complete"])
        self.assertEqual(set(receipt["files"]),
                         {"Experiment.esm", "Experiment - Main.ba2", "Experiment - Textures.ba2"})
        self.assertEqual(set(receipt["source_inputs"]),
                         {"plugin/Experiment.esm", "Data/Terrain/World.btd", "Data/Textures/FO4SF/icon.dds"})
        self.assertEqual((self.data / "Experiment - Main.ba2").read_bytes(), self.main.read_bytes())
        self.assertEqual((self.data / "Experiment - Textures.ba2").read_bytes(), self.texture.read_bytes())
        self.assertFalse((self.data / "Textures").exists())
        self.assertEqual(self.plugins.read_bytes(), self.original + b"*Experiment.esm\r\n")
        self.install_without_building()
        self.assertEqual((self.data / exp.RECORD).read_bytes(), record)
        exp.main(["uninstall", "--starfield", str(self.data.parent)])
        after = self.snapshot(self.root)
        history = [name for name in after if name not in before]
        self.assertEqual(len(history), 1)
        self.assertTrue(history[0].startswith("local/FO4SF/experiment-receipts/"))
        self.assertEqual(json.loads(gzip.decompress(after.pop(history[0]))), {**receipt, "cleanup_pending": True})
        self.assertEqual(after, before)

    def test_missing_main_or_texture_archive_never_builds(self):
        for path in (self.main, self.texture):
            with self.subTest(path=path.name):
                content = path.read_bytes()
                path.unlink()
                self.assert_refused()
                path.write_bytes(content)

    def test_wrong_texture_archive_refuses_before_publication(self):
        wrong = dict(self.textures)
        wrong[next(iter(wrong))] = piece_icons.dds(2, "different")
        for payload in (general_archive(self.textures), texture_archive(wrong), texture_archive({}),
                        texture_archive({"Textures/other.dds": next(iter(self.textures.values()))}), b"BTDX"):
            with self.subTest(payload=payload[:24]):
                self.texture.write_bytes(payload)
                self.assert_refused()

    def test_general_archive_must_cover_exactly_the_nontexture_inputs(self):
        for payload in (general_archive({**self.resources, **self.textures}), general_archive({}),
                        general_archive({"Terrain/World.btd": b"wrong"}), texture_archive(self.textures)):
            with self.subTest(payload=payload[:24]):
                self.main.write_bytes(payload)
                self.assert_refused()

    def test_default_keeps_textures_in_general_prebuilt_archive(self):
        self.argv.remove("--textures-archive")
        self.main.write_bytes(general_archive({**self.resources, **self.textures}))
        self.texture.unlink()
        self.install_without_building()
        receipt = json.loads((self.data / exp.RECORD).read_bytes())
        self.assertEqual(set(receipt["files"]), {"Experiment.esm", "Experiment - Main.ba2"})

    def test_texture_mode_without_texture_inputs_needs_only_main(self):
        (self.stage / "Data" / next(iter(self.textures))).unlink()
        (self.stage / "Data" / "Textures" / "FO4SF").rmdir()
        (self.stage / "Data" / "Textures").rmdir()
        self.texture.unlink()
        self.install_without_building()
        receipt = json.loads((self.data / exp.RECORD).read_bytes())
        self.assertEqual(set(receipt["files"]), {"Experiment.esm", "Experiment - Main.ba2"})

    def test_prepacked_still_requires_pack(self):
        self.argv.remove("--pack")
        self.assert_refused("requires --pack")
